import{_ as a,o,c as n,a2 as t}from"./chunks/framework.1C62pOns.js";const h=JSON.parse('{"title":"Integraciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/integracoes.md","filePath":"es/interface/integracoes.md","lastUpdated":1791311821000}'),l={name:"es/interface/integracoes.md"};function s(d,e,r,i,c,p){return o(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="integraciones" tabindex="-1">Integraciones <a class="header-anchor" href="#integraciones" aria-label="Permalink to &quot;Integraciones&quot;">​</a></h1><p>Llevan un agente o equipo a donde las personas ya conversan — WhatsApp, Teams, Telegram, correo — en vez de pedirles que entren en la plataforma.</p><p>Desde la versión 1.0.26.7 la plataforma ya no habla con cada canal por su cuenta: las integraciones de WhatsApp (Evolution API) y de Microsoft Teams fueron retiradas. Quien habla con el canal es <strong>N8N</strong>, que ya tiene un nodo listo para cada uno de ellos. La plataforma se ocupa de lo suyo: el agente, el equipo, el workflow.</p><h2 id="del-canal-a-la-plataforma" tabindex="-1">Del canal a la plataforma <a class="header-anchor" href="#del-canal-a-la-plataforma" aria-label="Permalink to &quot;Del canal a la plataforma&quot;">​</a></h2><p>El camino es siempre el mismo:</p><ol><li>un flujo de N8N recibe el mensaje del canal (el disparador de WhatsApp, de Teams…);</li><li>un nodo <strong>HTTP Request</strong> llama al workflow de la plataforma que conversa con el agente;</li><li>la respuesta del workflow vuelve al canal por el nodo de envío del propio N8N.</li></ol><p>La llamada es el disparo de workflow por API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/workflow/&lt;id&gt;/run</span></span>
<span class="line"><span>Authorization: Basic &lt;token de API de los workflows&gt;</span></span>
<span class="line"><span>X-Impersonate-User: &lt;usuario de la plataforma&gt;   (opcional)</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ &quot;mensaje&quot;: &quot;texto recibido&quot;, &quot;remitente&quot;: &quot;...&quot; }</span></span></code></pre></div><p>El cuerpo se convierte en el contexto de la ejecución, y la respuesta trae el resultado del workflow en el acto — no hace falta consultarlo después. El token es el de la pantalla de <a href="/pro-agent-hub-installer/es/interface/administracao">Administración</a>, y <code>X-Impersonate-User</code> decide en nombre de quién corre el workflow: sin él, corre como el usuario de servicio.</p><div class="tip custom-block"><p class="custom-block-title">Quién escribió el mensaje</p><p>Lo que viene del canal — nombre, número, correo — lo escribe quien envió el mensaje. Pase esos campos al agente como dato, nunca como instrucción, y no los use para decidir permisos.</p></div><h2 id="de-la-plataforma-a-n8n" tabindex="-1">De la plataforma a N8N <a class="header-anchor" href="#de-la-plataforma-a-n8n" aria-label="Permalink to &quot;De la plataforma a N8N&quot;">​</a></h2><blockquote><p>Registro en <strong>Configuración → pestaña N8N</strong>, solo para master.</p></blockquote><p>Una integración N8N guarda la <strong>dirección de la instancia</strong> (ej.: <code>https://n8n.empresa.com</code>, o <code>https://empresa.com/n8n</code> si N8N corre en una subruta; nunca con <code>/webhook/</code>), la <strong>autenticación</strong> del webhook y el <strong>plazo</strong> predeterminado de las llamadas.</p><p><strong>Autenticación.</strong> El nodo Webhook de N8N ofrece <em>Header Auth</em>, <em>Basic Auth</em>, <em>JWT Auth</em> o ninguna. Todas caben en el par encabezado/valor del registro:</p><table tabindex="0"><thead><tr><th>En el nodo Webhook</th><th>Encabezado</th><th>Valor</th></tr></thead><tbody><tr><td>Header Auth</td><td>el <em>Name</em> de la credencial</td><td>el <em>Value</em> de la credencial</td></tr><tr><td>Basic Auth</td><td><code>Authorization</code></td><td><code>Basic </code> + base64 de <code>usuario:contraseña</code></td></tr><tr><td>JWT Auth</td><td><code>Authorization</code></td><td><code>Bearer </code> + el token</td></tr></tbody></table><p>El secreto nunca vuelve a la pantalla: al editar, deje el campo en blanco para mantener el actual, o marque <em>Quitar el secreto actual</em>. Tampoco queda en el workflow — el flujo guarda solo el número de la integración y la ruta del webhook, y por eso quien arma el workflow no puede enviar la llamada a otro lugar.</p><p>En <strong>Avanzado</strong> están los prefijos <code>webhook</code> y <code>webhook-test</code>. Cámbielos solo si la instancia de N8N los reemplazó con <code>N8N_ENDPOINT_WEBHOOK</code> y <code>N8N_ENDPOINT_WEBHOOK_TEST</code>.</p><p>En un workflow high-code (o en un nodo Script), la llamada es:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">respuesta </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> call_n8n(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pedido-aprobado&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pedido&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cliente&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACME&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><ul><li>el primer argumento es el número de la integración (aparece en la lista de la pestaña);</li><li>el segundo es el <em>Path</em> del nodo Webhook; con parámetros de ruta, indique los valores (el Path <code>pedido/:id</code> se vuelve <code>&quot;pedido/123&quot;</code>);</li><li>el tercero son los datos: van como JSON en el cuerpo (en N8N, <code>$json.body</code>); en <code>GET</code> y <code>HEAD</code> se vuelven parámetros de la URL (<code>$json.query</code>). N8N limita el cuerpo a 16 MB.</li></ul><p>El método es el <em>HTTP Method</em> del nodo (<code>method=&quot;GET&quot;</code>, por ejemplo; el predeterminado es <code>POST</code>). La respuesta depende del <em>Respond</em> del nodo Webhook:</p><table tabindex="0"><thead><tr><th>Respond</th><th>Lo que devuelve <code>call_n8n</code></th></tr></thead><tbody><tr><td>Immediately</td><td>el mensaje de que el flujo empezó — sigue por su cuenta</td></tr><tr><td>When Last Node Finishes</td><td>la salida del último nodo</td></tr><tr><td>Using &#39;Respond to Webhook&#39; Node</td><td>lo que ese nodo defina</td></tr></tbody></table><p>El JSON se vuelve diccionario, el texto queda como texto y un archivo (un PDF, por ejemplo) se vuelve bytes. La URL de <strong>producción</strong> solo existe con el flujo publicado en N8N; la de <strong>prueba</strong> (<code>test_mode=True</code>) solo responde mientras el editor está en <em>Listen for test event</em>, durante 120 segundos. Un webhook no registrado responde 404, y el mensaje de error lo dice. En N8N Cloud, un flujo que no responde en 100 segundos falla.</p><p>Una falla — integración deshabilitada, red, respuesta de error de N8N — lanza <code>N8nCallError</code>, con <code>status</code> y <code>body</code> cuando N8N respondió. La referencia completa está en <a href="/pro-agent-hub-installer/es/funcoes/workflow_highcode">Funciones</a>.</p><h3 id="en-el-workflow-low-code" tabindex="-1">En el workflow low-code <a class="header-anchor" href="#en-el-workflow-low-code" aria-label="Permalink to &quot;En el workflow low-code&quot;">​</a></h3><p>El nodo <strong>N8N</strong> (grupo <em>Integraciones</em> de la paleta) hace la misma llamada sin código: elija la integración, indique la ruta del webhook (acepta <code>{{variable}}</code>, como en <code>pedido/{{pedido_id}}</code>), el método y los datos — una variable, una referencia <code>{{nodo.campo}}</code> o un JSON con variables. La respuesta va a la variable de salida (<code>n8n_result</code>). El nodo tiene dos salidas, <strong>OK</strong> y <strong>ERROR</strong>, como el nodo Planificador: la falla sale por ERROR cuando está conectada, y el motivo queda en <code>{{nombre_del_nodo.n8nError}}</code>. <em>Cuando falle</em> elige entre continuar, detener el camino o fallar el workflow.</p><p>Al exportar la configuración, las integraciones N8N van incluidas, con el secreto cifrado como las demás contraseñas.</p>`,27)])])}const m=a(l,[["render",s]]);export{h as __pageData,m as default};
